export const getFakeBoardingCards = (partial: boolean = false): PrintBoardingCardsData => {
    const model = structuredClone(fakeBoardingCards);
    let boardingCards = model.boardingCards;

    if (partial) {
        const partialBoardingCards = structuredClone(boardingCards.slice(0, 1));
        partialBoardingCards[0].passengers.splice(1);

        boardingCards = partialBoardingCards;
    }

    return {
        ...model,
        boardingCards
    };
};
